// Generated by AI
import { describe, expect, it, vi } from 'vitest';
import { LIMITS, parseSessionEvent, type SessionEvent } from '@felan-ai/session-protocol';
import { createSessionState, reduceSession } from '../src/client/reducer.js';
import { delta, snapshot } from './client-fixtures.js';

const event = (rev: number, change: unknown): SessionEvent => parseSessionEvent({ v: 1, session: 'session', rev, change });
const live = () => reduceSession(createSessionState('session'), { type: 'snapshot', snapshot: snapshot() });

describe('declarative session reducer', () => {
  it('recovers regressive UI element revisions while accepting revisionless status updates', () => {
    const doc = { id: 'doc', kind: 'document', revision: 5, title: 'Document', markdown: 'Content', fallback: 'Document', actions: [] } as const;
    let state = reduceSession(live(), { type: 'update', update: event(1, { type: 'presentation.updated', presentation: doc }) });
    state = reduceSession(state, { type: 'update', update: event(2, { type: 'presentation.updated', presentation: { ...doc, revision: 4 } }) });
    expect(state.status).toBe('recovering');
    expect(state.snapshot?.presentation[0]).toMatchObject({ revision: 5 });
    state = reduceSession(state, { type: 'snapshot', snapshot: { ...snapshot(2), presentation: [{ ...doc, revision: 6, actions: [] }] } });
    expect(state.status).toBe('live');
    const status = { id: 'status', kind: 'status', key: 'count', value: { kind: 'tokens', value: 1 }, fallback: 'One token' };
    state = reduceSession(state, { type: 'update', update: event(3, { type: 'presentation.updated', presentation: status }) });
    state = reduceSession(state, { type: 'update', update: event(4, { type: 'presentation.updated', presentation: { ...status, value: { kind: 'tokens', value: 2 } } }) });
    expect(state.status).toBe('live');
    expect(state.snapshot?.presentation.find(item => item.id === 'status')).toMatchObject({ value: { value: 2 } });
  });

  it('converges on duplicates, unknown additions and coalesced tool replacements', () => {
    const tool = { id: 'tool', name: 'read', message: 'message', state: 'running', output: 'a', truncated: false };
    const events = [event(1, { type: 'future.optional', data: true }), event(2, { type: 'tool.updated', tool }),
      event(3, { type: 'tool.updated', tool: { ...tool, state: 'completed', output: 'abc' } })];
    const run = (duplicates: boolean) => events.flatMap(value => duplicates ? [value, value] : [value]).reduce(
      (state, value) => reduceSession(state, { type: 'update', update: value }), live());
    expect(run(true)).toEqual(run(false));
    expect(run(true).snapshot?.tools).toEqual([{ ...tool, state: 'completed', output: 'abc' }]);
  });
  it('buffers out-of-order and missing revisions and recovers at an atomic snapshot', () => {
    const late = event(3, { type: 'model.updated', model: { provider: 'fixture', id: 'new' }, thinking: 'high' });
    let state = reduceSession(live(), { type: 'update', update: late });
    expect(state.status).toBe('recovering');
    state = reduceSession(state, { type: 'update', update: event(2, { type: 'future.optional' }) });
    state = reduceSession(state, { type: 'snapshot', snapshot: snapshot(2) });
    expect(state.status).toBe('live');
    expect(state.snapshot?.revision).toBe(3);
    expect(state.snapshot?.thinking).toBe('high');
  });
  it('reconstructs a snapshot/live race using both revision and independent Unicode offsets', () => {
    let state = createSessionState('session');
    state = reduceSession(state, { type: 'update', update: delta('😀', 1) });
    state = reduceSession(state, { type: 'update', update: delta('思', 0, 'thinking') });
    const cut = snapshot(); cut.activeStreams = [{ id: 'assistant', message: 'message', kind: 'assistant', text: 'A', offset: 1 }];
    state = reduceSession(state, { type: 'snapshot', snapshot: cut });
    state = reduceSession(state, { type: 'update', update: delta('😀', 1) });
    state = reduceSession(state, { type: 'update', update: delta('考', 1, 'thinking') });
    expect(state.snapshot?.activeStreams.map(stream => [stream.kind, stream.text, stream.offset])).toEqual([['assistant', 'A😀', 2], ['thinking', '思考', 2]]);
  });
  it('starts an absent prefix only at zero; recovers a gap once then waits for completion', () => {
    let state = reduceSession(live(), { type: 'update', update: delta('missing', 4) });
    expect(state.status).toBe('recovering');
    state = reduceSession(state, { type: 'snapshot', snapshot: snapshot() });
    expect(state.status).toBe('live');
    expect(state.snapshot?.completionOnlyStreams[0]?.id).toBe('assistant');
    state = reduceSession(state, { type: 'update', update: delta('ignore', 0) });
    expect(state.snapshot?.activeStreams).toEqual([]);
    state = reduceSession(state, { type: 'update', update: event(1, { type: 'message.completed', message: {
      id: 'message', entryId: 'entry', role: 'assistant', timestamp: 1, content: [{ type: 'text', text: 'authoritative' }],
    } }) });
    state = reduceSession(state, { type: 'update', update: delta('late', 0) });
    expect(state.snapshot?.completionOnlyStreams).toEqual([]);
    expect(state.snapshot?.activeStreams).toEqual([]);
    expect(state.snapshot?.history.entries[0]?.content).toEqual([{ type: 'text', text: 'authoritative' }]);
  });
  it('accepts a recovered prefix, but ignores explicitly completion-only streams', () => {
    let state = reduceSession(live(), { type: 'update', update: delta('✓', 2) });
    const cut = snapshot(); cut.activeStreams = [{ id: 'assistant', message: 'message', kind: 'assistant', text: 'A😀', offset: 2 }];
    state = reduceSession(state, { type: 'snapshot', snapshot: cut });
    expect(state.snapshot?.activeStreams[0]?.text).toBe('A😀✓');
    state = reduceSession(state, { type: 'update', update: event(1, { type: 'stream.completion_only', stream: { id: 'assistant', message: 'message', kind: 'assistant', reason: 'limit' } }) });
    state = reduceSession(state, { type: 'update', update: delta('ignored', 3) });
    expect(state.snapshot?.completionOnlyStreams[0]?.reason).toBe('limit');
    expect(state.snapshot?.activeStreams).toEqual([]);
  });
  it('never applies a delta for a different message while a message is open', () => {
    let state = reduceSession(live(), { type: 'update', update: delta('open') });
    state = reduceSession(state, { type: 'update', update: delta('wrong', 0, 'thinking', 'other') });
    expect(state.status).toBe('recovering');
    expect(state.snapshot?.activeStreams.map(stream => stream.text)).toEqual(['open']);
  });
  it('bounds buffered events and recovery attempts without fabricating revisions', () => {
    let state = live();
    for (let i = 0; i < 1030; i++) state = reduceSession(state, { type: 'update', update: event(10, { type: 'future.optional' }) });
    expect(state.buffered.length).toBeLessThanOrEqual(1024);
    expect(state.snapshot?.revision).toBe(0);
    for (let i = 0; i < 4; i++) state = reduceSession(state, { type: 'recovery_started' });
    expect(state.status).toBe('blocked');
  });
  it('retains overflow invalidation until a snapshot requested after the loss', () => {
    let state = live();
    const requestedGeneration = state.bufferGeneration;
    for (let rev = 2; rev < 1030; rev++) state = reduceSession(state, { type: 'update', update: event(rev, { type: 'future.optional' }) });
    expect(state.bufferGeneration).toBeGreaterThan(requestedGeneration);
    state = reduceSession(state, { type: 'snapshot', snapshot: snapshot(1029), bufferGeneration: requestedGeneration });
    expect(state.status).toBe('recovering');
    state = reduceSession(state, { type: 'snapshot', snapshot: snapshot(1029), bufferGeneration: state.bufferGeneration });
    expect(state.status).toBe('live'); expect(state.snapshot?.revision).toBe(1029);
  });
  it('rejects regressive and cross-session snapshots and keeps disconnect distinct from cancellation', () => {
    let state = reduceSession(live(), { type: 'snapshot', snapshot: snapshot(2) });
    state = reduceSession(state, { type: 'snapshot', snapshot: snapshot(1) });
    expect(state.status).toBe('recovering'); expect(state.snapshot?.revision).toBe(2);
    expect(() => reduceSession(state, { type: 'snapshot', snapshot: { ...snapshot(), session: 'other' } })).toThrow(/mismatch/);
    const running = snapshot(); running.run = { state: 'running', id: 'run' };
    state = reduceSession(live(), { type: 'snapshot', snapshot: running });
    state = reduceSession(state, { type: 'disconnected' });
    expect(state.snapshot?.run).toEqual({ state: 'running', id: 'run' });
  });
});

describe('recovery causes', () => {
  const tool = (id: string, output = '') => ({ id, name: 'read', message: 'message', state: 'completed', output, truncated: false });

  it('names a revision gap, a resync request and a stale snapshot', () => {
    expect(reduceSession(live(), { type: 'update', update: event(3, { type: 'future.optional' }) })).toMatchObject({ status: 'recovering', recoveryCause: 'revision_gap' });
    expect(reduceSession(live(), { type: 'resync', cause: 'daemon_resync' })).toMatchObject({ status: 'recovering', recoveryCause: 'daemon_resync' });
    const ahead = reduceSession(createSessionState('session'), { type: 'snapshot', snapshot: snapshot(4) });
    expect(reduceSession(ahead, { type: 'snapshot', snapshot: snapshot(2) })).toMatchObject({ status: 'recovering', recoveryCause: 'stale_snapshot' });
  });

  it('keeps the latest 256 tools like the daemon, dropping the oldest finished ones instead of resynchronizing', () => {
    const tools = Array.from({ length: LIMITS.pageEntries }, (_, index) => ({ ...tool(`tool-${index}`), ...(index === 0 ? { state: 'running' } : {}) }));
    const full = reduceSession(createSessionState('session'), { type: 'snapshot', snapshot: { ...snapshot(), tools } });
    const next = reduceSession(full, { type: 'update', update: event(1, { type: 'tool.updated', tool: tool('new') }) });
    expect(next.status).toBe('live');
    expect(next.snapshot!.tools.map(item => item.id)).toEqual(['tool-0', ...tools.slice(2).map(item => item.id), 'new']);
  });

  it('keeps only the newest 256 tools when all of them are running', () => {
    const running = Array.from({ length: LIMITS.pageEntries }, (_, index) => ({ ...tool(`tool-${index}`), state: 'running' }));
    const state = reduceSession(createSessionState('session'), { type: 'snapshot', snapshot: { ...snapshot(), tools: running } });
    const next = reduceSession(state, { type: 'update', update: event(1, { type: 'tool.updated', tool: { ...tool('new'), state: 'running' } }) });
    expect(next.status).toBe('live');
    expect(next.snapshot!.tools.map(item => item.id)).toEqual([...running.slice(1).map(item => item.id), 'new']);
  });

  it('keeps running and recently updated processes, matching the daemon\'s last-updated order', () => {
    const process = (id: string, state = 'exited') => ({ id, session: 'session', root: 'session', kind: 'foreground', state, command: id, startedAt: 1, controllable: false, outputOffset: 0 });
    const processes = Array.from({ length: LIMITS.pageEntries }, (_, index) => process(`process-${index}`, index === 0 ? 'running' : 'exited'));
    let state = reduceSession(createSessionState('session'), { type: 'snapshot', snapshot: { ...snapshot(), processes } });
    state = reduceSession(state, { type: 'update', update: event(1, { type: 'process.updated', process: process('new', 'running') }) });
    state = reduceSession(state, { type: 'update', update: event(2, { type: 'process.updated', process: process('process-5', 'exited') }) });
    state = reduceSession(state, { type: 'update', update: event(3, { type: 'process.updated', process: process('new') }) });
    expect(state.status).toBe('live');
    const ids = state.snapshot!.processes.map(item => item.id);
    expect(ids).toHaveLength(LIMITS.pageEntries);
    expect(ids.slice(0, 2)).toEqual(['process-0', 'process-2']);
    expect(ids.slice(-2)).toEqual(['process-5', 'new']);
  });

  it('trims children past the limit, keeping active runs', () => {
    const child = (index: number, run = 'idle') => ({ session: `child-${index}`, parent: 'session', root: 'session', title: '', run: { state: run }, state: 'open' });
    const children = Array.from({ length: LIMITS.pageEntries + 2 }, (_, index) => child(index, index === 0 ? 'running' : 'idle'));
    const state = reduceSession(createSessionState('session'), { type: 'snapshot', snapshot: { ...snapshot(), children } });
    const next = reduceSession(state, { type: 'update', update: event(1, { type: 'run.updated', run: { state: 'idle' } }) });
    expect(next.status).toBe('live');
    expect(next.snapshot!.children.map(item => item.session)).toEqual(['child-0', ...children.slice(3).map(item => item.session)]);
  });

  it('drops resolved interactions like the daemon snapshot, so they never accumulate', () => {
    const waiting = { id: 'question', scope: { kind: 'session', session: 'session', root: 'session' },
      request: { kind: 'confirm', title: 'Continue?', message: 'Confirm' }, createdAt: 1, state: 'waiting' };
    let state = reduceSession(live(), { type: 'update', update: event(1, { type: 'interaction.requested', interaction: waiting }) });
    expect(state.snapshot!.interactions.map(item => item.id)).toEqual(['question']);
    state = reduceSession(state, { type: 'update', update: event(2, { type: 'interaction.resolved',
      interaction: { ...waiting, state: 'cancelled', resolvedAt: 2, result: { cancelled: true, reason: 'user' } } }) });
    expect(state.status).toBe('live');
    expect(state.snapshot!.interactions).toEqual([]);
  });
});

describe('snapshot size accounting', () => {
  const bytes = (value: unknown) => Buffer.byteLength(JSON.stringify(value));
  function nearLimit(spareBytes: number) {
    const cut = snapshot();
    cut.title = '';
    cut.title = 'x'.repeat(LIMITS.pageBytes - bytes(cut) - spareBytes);
    return cut;
  }

  it('starts with the exact snapshot size and serializes only changes for a 5 MiB session', () => {
    const cut = snapshot();
    cut.tools = Array.from({ length: 80 }, (_, index) => ({ id: `tool-${index}`, name: 'read', message: 'message',
      state: 'completed', output: 'x'.repeat(64 * 1024 - 16), truncated: false }));
    let state = reduceSession(createSessionState('session'), { type: 'snapshot', snapshot: cut });
    const initialBytes = bytes(cut);
    expect(state.snapshotBytes).toBe(initialBytes);
    const changes = Array.from({ length: 1000 }, (_, index) => event(index + 1, { type: 'run.updated', run: { state: 'idle' } }));
    const stringify = vi.spyOn(JSON, 'stringify');
    try {
      for (const update of changes) state = reduceSession(state, { type: 'update', update });
      expect(stringify.mock.calls.map(call => call[0])).toEqual(changes.map(update => update.change));
      expect(state.status).toBe('live');
    } finally { stringify.mockRestore(); }
    expect(state.snapshotBytes).toBe(initialBytes + changes.reduce((sum, update) => sum + bytes(update.change), 0));
    expect(state.snapshotBytes).toBeGreaterThanOrEqual(bytes(state.snapshot));
  });

  it('recomputes an overestimate instead of rejecting a state that still fits', () => {
    const state = reduceSession(createSessionState('session'), { type: 'snapshot', snapshot: nearLimit(16) });
    const update = event(1, { type: 'run.updated', run: { state: 'idle' } });
    expect(state.snapshotBytes + bytes(update.change)).toBeGreaterThan(LIMITS.pageBytes);
    const next = reduceSession(state, { type: 'update', update });
    expect(next.status).toBe('live');
    expect(next.snapshotBytes).toBe(bytes(next.snapshot));
    expect(next.snapshotBytes).toBeLessThanOrEqual(LIMITS.pageBytes);
  });

  it('resets the estimate when a newer snapshot replaces accumulated changes', () => {
    let state = live();
    state = reduceSession(state, { type: 'update', update: event(1, { type: 'run.updated', run: { state: 'idle' } }) });
    expect(state.snapshotBytes).toBeGreaterThan(bytes(state.snapshot));
    const cut = snapshot(2);
    state = reduceSession(state, { type: 'snapshot', snapshot: cut });
    expect(state.snapshotBytes).toBe(bytes(cut));
  });

  it('rejects a growing state without accepting its revision or changing the byte bound', () => {
    const state = reduceSession(createSessionState('session'), { type: 'snapshot', snapshot: nearLimit(4) });
    const update = event(1, { type: 'run.updated', run: { state: 'running', id: 'run' } });
    const next = reduceSession(state, { type: 'update', update });
    expect(next).toMatchObject({ status: 'recovering', recoveryCause: 'state_size_limit', snapshotBytes: state.snapshotBytes, buffered: [update] });
    expect(next.snapshot).toBe(state.snapshot);
    expect(next.snapshot?.revision).toBe(0);
  });

  it('accounts for escaped Unicode stream growth before accepting a later revision', () => {
    const state = reduceSession(createSessionState('session'), { type: 'snapshot', snapshot: nearLimit(256) });
    const streamed = reduceSession(state, { type: 'update', update: delta('😀\n'.repeat(16)) });
    expect(streamed.status).toBe('live');
    expect(streamed.snapshotBytes).toBeGreaterThanOrEqual(bytes(streamed.snapshot));
    const next = reduceSession(streamed, { type: 'update', update: event(1, { type: 'run.updated', run: { state: 'running', id: 'x'.repeat(128) } }) });
    expect(next).toMatchObject({ status: 'recovering', recoveryCause: 'state_size_limit' });
    expect(next.snapshot).toBe(streamed.snapshot);
  });

  it('rejects streams and snapshots whose exact size exceeds the limit', () => {
    const state = reduceSession(createSessionState('session'), { type: 'snapshot', snapshot: nearLimit(4) });
    const streamed = reduceSession(state, { type: 'update', update: delta('😀\n') });
    expect(streamed).toMatchObject({ status: 'recovering', recoveryCause: 'state_size_limit' });
    expect(streamed.snapshot).toBe(state.snapshot);
    const oversized = reduceSession(state, { type: 'snapshot', snapshot: nearLimit(-1) });
    expect(oversized).toMatchObject({ status: 'recovering', recoveryCause: 'state_size_limit' });
    expect(oversized.snapshot).toBe(state.snapshot);
  });
});

describe('stream byte accounting', () => {
  it.each(['x', '思', '😀', '\ud800'])('keeps exact per-stream limits for %j', character => {
    const width = Buffer.byteLength(character);
    const text = character.repeat(Math.floor((LIMITS.activeStreamBytes - 1) / width))
      + 'x'.repeat((LIMITS.activeStreamBytes - 1) % width);
    const cut = snapshot();
    cut.activeStreams = [{ id: 'assistant', message: 'message', kind: 'assistant', text, offset: Array.from(text).length }];
    let state = reduceSession(createSessionState('session'), { type: 'snapshot', snapshot: cut });
    state = reduceSession(state, { type: 'update', update: delta('x', cut.activeStreams[0]!.offset) });
    expect(state.status).toBe('live');
    expect(Buffer.byteLength(state.snapshot!.activeStreams[0]!.text)).toBe(LIMITS.activeStreamBytes);
    const next = reduceSession(state, { type: 'update', update: delta('x', state.snapshot!.activeStreams[0]!.offset) });
    expect(next).toMatchObject({ status: 'recovering', recoveryCause: 'stream_limit' });
    expect(next.snapshot).toBe(state.snapshot);
  });

  it.each(['x', '思'])('keeps the exact combined stream limit for %j', character => {
    const width = Buffer.byteLength(character);
    const full = character.repeat(Math.floor(LIMITS.activeStreamBytes / width)) + 'x'.repeat(LIMITS.activeStreamBytes % width);
    const cut = snapshot();
    cut.activeStreams = Array.from({ length: 4 }, (_, index) => {
      const text = index === 3 ? full.slice(0, -1) : full;
      return { id: index === 3 ? 'assistant' : `stream-${index}`, message: 'message', kind: 'assistant' as const,
        text, offset: Array.from(text).length };
    });
    let state = reduceSession(createSessionState('session'), { type: 'snapshot', snapshot: cut });
    state = reduceSession(state, { type: 'update', update: delta('x', cut.activeStreams[3]!.offset) });
    expect(state.status).toBe('live');
    expect(state.snapshot!.activeStreams.reduce((sum, stream) => sum + Buffer.byteLength(stream.text), 0)).toBe(LIMITS.activeStreamsBytes);
    const next = reduceSession(state, { type: 'update', update: delta('x', 0, 'thinking') });
    expect(next).toMatchObject({ status: 'recovering', recoveryCause: 'stream_limit' });
    expect(next.snapshot).toBe(state.snapshot);
  });

  it('encodes only delta-sized data while a long stream remains below the conservative limit', () => {
    let state = live();
    const encode = vi.spyOn(TextEncoder.prototype, 'encodeInto');
    const steps = 4096;
    const text = 'x'.repeat(64);
    try {
      for (let index = 0; index < steps; index++) state = reduceSession(state, { type: 'update', update: delta(text, index * text.length) });
      expect(state.status).toBe('live');
      expect(state.snapshot!.activeStreams[0]!.text.length).toBe(steps * text.length);
      expect(encode.mock.calls.reduce((sum, [input]) => sum + input.length, 0)).toBeLessThan(steps * 512);
      expect(encode.mock.calls.every(([input]) => input.length < 512)).toBe(true);
    } finally { encode.mockRestore(); }
  });
});
